const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mascot=`<svg class="mascot" viewBox="0 0 180 195" fill="none" aria-hidden="true"><ellipse cx="90" cy="180" rx="64" ry="9" fill="#c6b5ed" opacity=".4"/><path d="M40 110c0-42 100-42 100 0v38c0 42-100 42-100 0z" fill="#8055d9"/><path d="M48 108c0-26 84-26 84 0v24c0 30-84 30-84 0z" fill="#f7f0ff"/><path d="M61 113c0-7 9-7 9 0m40 0c0-7 9-7 9 0" stroke="#5e398f" stroke-width="5" stroke-linecap="round"/><path d="M79 128q11 11 22 0" stroke="#7145a2" stroke-width="4" stroke-linecap="round"/><circle cx="58" cy="127" r="7" fill="#f1c8d9"/><circle cx="123" cy="127" r="7" fill="#f1c8d9"/><path d="M25 63 90 35l65 28-65 29z" fill="#312445"/><path d="M49 75v20q41 19 82 0V75L90 91z" fill="#4a3268"/><path d="M151 65v39" stroke="#edbd66" stroke-width="3"/><circle cx="151" cy="107" r="5" fill="#edbd66"/><path d="m41 135-15 21m114-21 15 21" stroke="#8055d9" stroke-width="14" stroke-linecap="round"/><path d="m66 172-6 12m54-12 6 12" stroke="#563490" stroke-width="12" stroke-linecap="round"/><path d="M86 157h9m-4-4v8" stroke="#e5d6ff" stroke-width="3" stroke-linecap="round"/><path d="M140 29v14m-7-7h14M35 25v10m-5-5h10" stroke="#b396e5" stroke-width="3" stroke-linecap="round"/></svg>`;
let session=null,data=null,chapter=null,lesson=null,stepIndex=0,selected=null,checked=false,runtimePromise=null,running=false,consoleText='',lastRun=null,environment='',outputTab='console',chat=[],saveTimer,exam=null,examTimer,examQueue=Promise.resolve(),saveQueue=Promise.resolve();
let resendRequested=false;let chapterProgress={};const drafts={},chatByChapter={},plots=[];
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,5000);}
async function api(route,body){const r=await fetch('/api/'+route,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json','X-Agstat-Request':'classroom'},body:body===undefined?undefined:JSON.stringify(body)});const result=await r.json();if(!r.ok){if(r.status===403&&/approval|Verify your email/.test(result.error||'')&&session){session.access=false;data=null;render();}throw Object.assign(new Error(result.error||'The service could not respond.'),{status:r.status});}return result;}
function asset(url){if(!url)return '#';if(/^https?:/.test(url))return url;return '/learning-assets/'+url.replace(/^\//,'');}
function passed(id){return chapterProgress['r-agriculture_'+id]?.stepIds||[];}
function completed(c){const total=data.learning.chapters.find(x=>x.id===c.id)?.steps.length||0;return total>0&&passed(c.id).length===total;}
function stats(){const all=data?.learning.chapters.flatMap(c=>c.steps)||[];const n=Object.values(chapterProgress).reduce((a,p)=>a+(p.stepIds?.length||0),0);return {n,total:all.length,xp:n*10,chapters:data?.course.chapters.filter(completed).length||0};}
function markdown(raw){
 const code=[];let text=String(raw||'').replace(/(`{3,})[^\n]*\n([\s\S]*?)\n\1/g,(_,fence,s)=>`\n\n@@CODE${code.push(s)-1}@@\n\n`);
 text=escape(text).replace(/!\[([^\]]*)\]\(([^\s)]+)(?:[^)]*)\)(?:\{[^}]*\})?/g,(_,alt,url)=>{if(!/^(images|figures|screenshots|assets)\/[\w./%+-]+$/.test(url))return `<p>${alt} — see the complete chapter for this illustration.</p>`;return `<img src="${asset('books/r-agriculture/'+url)}" alt="${alt}" loading="lazy">`;});
 text=text.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1 ↗</a>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\{#[^}]+\}/g,'');
 return text.split(/\n\s*\n/).map(p=>{if(/^@@CODE\d+@@$/.test(p.trim()))return `<pre>${escape(code[Number(p.match(/\d+/)[0])])}</pre>`;if(p.trim().startsWith('|'))return '<table>'+p.split('\n').filter(x=>!/^\|?[\s:|-]+$/.test(x)).map(row=>'<tr>'+row.split('|').filter((_,i,a)=>i>0&&i<a.length-1).map(x=>'<td>'+x.trim()+'</td>').join('')+'</tr>').join('')+'</table>';return '<p>'+p.replace(/\n/g,'<br>')+'</p>';}).join('');
}
function landing(){return `<section class="hero"><div><span class="pill purple">LEARN R. THINK LIKE A SCIENTIST.</span><h1>Learn R.<br><em>Explore agricultural data.</em></h1><p>Your interactive agricultural statistics classroom. Learn with STAT MAASH, experiment in real R, and build understanding one challenge at a time.</p><button class="btn primary open-auth">Enter your classroom →</button><p><small>For registered students approved by the department.</small></p></div><div class="hero-art">${mascot}<span class="float-tag">✦ Your AI learning companion</span><span class="float-tag">&gt; let's grow together_</span></div></section><div class="feature-grid">${[['⌘','A real R workspace','Write code, explore data, and watch your plots come to life.'],['✧','Guidance that stays with you','STAT MAASH helps you reason through code, errors, and agricultural results.'],['✓','Learn. Try. Understand.','Interactive lessons, self-assessment, and practical challenges at your pace.']].map(x=>`<article class="card"><span class="feature-icon">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div>`;}
function studentProfileForm(){const d=session.user.details||{};return `<section class="profile-onboarding card"><span class="eyebrow">ONE-TIME STUDENT REGISTRATION</span><h1>Complete your student details</h1><p>Signed in as <strong>${escape(session.user.email)}</strong>. Submit these details once. Your teacher will review and approve your course access.</p><form id="student-profile-form"><label>Full name<input name="name" required minlength="2" maxlength="80" autocomplete="name" value="${escape(d.name==='Student'?'':d.name)}"></label><label>Roll number<input name="rollNo" required maxlength="40" autocomplete="off" placeholder="Your university roll number" value="${escape(d.rollNo)}"></label><label>Degree programme<select name="degree" required><option value="">Select your degree</option>${['BSc Hons Agriculture','BTech Biotechnology'].map(x=>`<option ${d.degree===x?'selected':''}>${x}</option>`).join('')}</select></label><label>WhatsApp number<input name="whatsapp" type="tel" required minlength="8" maxlength="25" inputmode="tel" autocomplete="tel" placeholder="Include country code if needed" value="${escape(d.whatsapp)}"></label><button class="btn primary" type="submit">Submit for Teacher approval</button><p id="profile-status" role="status"></p></form><small>Your details are visible to you and your teacher. Contact your teacher if a correction is needed after submission.</small></section>`;}
function waiting(){const u=session.user;return `<section class="card gate">${mascot}<span class="pill ${u.status==='suspended'?'amber':'purple'}">${u.status==='suspended'?'ACCESS SUSPENDED':'YOUR STUDENT ACCOUNT'}</span><h1>${!u.verified?'One small step: verify your email.':u.status==='suspended'?'Please contact the department.':'You’re registered. Approval is next.'}</h1><p>Hello ${escape(u.name)}. ${!u.verified?'Open the latest verification email, then return here and select Check email verification.':'Your teacher must approve your account before you can open lessons, books, or the R classroom.'}</p><p><strong>${escape(u.email)}</strong></p><div class="status-steps"><span class="done">✓ Registered</span><span class="${u.verified?'done':''}">${u.verified?'✓':'2'} Email verified</span><span class="${u.status==='approved'?'done':''}">${u.status==='approved'?'✓ Teacher approved':'3 Teacher approval'}</span></div><button class="btn primary" id="refresh-access">${!u.verified?'Check email verification ↻':'Check approval status ↻'}</button>${!u.verified?'<button class="btn subtle" id="resend-verification">Send a fresh verification email</button>':''} <button class="btn subtle" id="signout">Sign out</button><p><small>Use the newest verification link. If it has expired, choose Send a fresh verification email above.</small></p></section>`;}
function chapterCleared(id){const r=data.ratings?.['r-agriculture_'+id];return r?.passed===true||(r?.total>0&&r.score===r.total);}
function activeChapter(){return data.course.chapters.find(c=>!chapterCleared(c.id))||data.course.chapters.at(-1);}
function readingDone(id){const p=chapterProgress['r-agriculture_'+id]||{};return p.readComplete===true||topicGroups(id).every(g=>g.items.filter(s=>s.kind==='learn').every(s=>p.stepIds?.includes(s.id)));}
function assessmentReady(id){return readingDone(id)&&(!data.videos?.[id]||chapterProgress['r-agriculture_'+id]?.videoComplete===true);}
function chapterLayout(id,section,content){const c=data.course.chapters.find(x=>x.id===id),p=chapterProgress['r-agriculture_'+id]||{},ready=assessmentReady(id),cleared=chapterCleared(id),teacher=session.user.admin;return `<div class="course-learning-page"><a href="#home" class="course-back">← ${teacher?'Teaching dashboard':'My course'}</a><div class="course-title"><span>R PROGRAMMING FOR AGRICULTURAL DATA ANALYSIS</span><h1>${escape(c.title)}</h1><small>Chapter ${Number(id)} of 14</small></div><div class="course-player-layout"><aside class="course-sections"><h2>Chapter content</h2><a class="${section==='video'?'selected':''}" href="#watch/${id}"><span>▷</span><div><strong>Video lecture</strong><small>${p.videoComplete?'Completed':data.videos?.[id]?'Watch lecture':'Video coming soon'}</small></div>${p.videoComplete?'✓':''}</a><a class="${section==='reading'?'selected':''}" href="#read/${id}"><span>▤</span><div><strong>Chapter reading</strong><small>${readingDone(id)?'Completed':'Full chapter text & examples'}</small></div>${readingDone(id)?'✓':''}</a>${ready||cleared||teacher?`<a class="${section==='assessment'?'selected':''}" href="#assess/${id}"><span>✓</span><div><strong>Assessment</strong><small>${cleared?'Passed':'Check your understanding'}</small></div></a>`:'<div class="course-section-locked"><span>🔒</span><div><strong>Assessment</strong><small>Complete the available lecture and reading</small></div></div>'}<div class="course-unlock">${cleared?'✓ Chapter passed':'Next chapter unlocks when you pass this assessment.'}</div><details class="course-extra"><summary>Optional R practice</summary><p>Experiment with R or ask STAT MAASH for help.</p><a class="btn subtle small" href="#practise/${id}">Open R lab</a></details></aside><section class="course-main-content">${content}</section></div></div>`;}
function lecturePlayer(id){const v=data.videos?.[id];if(!v)return '<div class="lecture-placeholder"><span>▷</span><h2>Video lecture coming soon</h2><p>Your teacher will add the lecture here. You can read the chapter now.</p></div>';return v.provider==='file'?`<video class="lecture-player" controls playsinline preload="metadata" src="${escape(v.url)}"><a href="${escape(v.url)}">Open video lecture</a></video>`:`<iframe class="lecture-player" title="Chapter ${id} video lecture" src="${escape(v.url)}" allow="accelerometer; encrypted-media; picture-in-picture; fullscreen" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`;}
function studentWatch(id){const p=chapterProgress['r-agriculture_'+id]||{};return chapterLayout(id,'video',`<article class="course-content-card"><h2>Video lecture</h2>${lecturePlayer(id)}<div class="course-lesson-footer">${data.videos?.[id]?`<button class="btn primary" data-complete-lesson="video" data-chapter="${id}">${p.videoComplete?'Continue to reading →':'Mark lecture complete & read →'}</button>`:`<a class="btn primary" href="#read/${id}">Read chapter →</a>`}</div></article>`);}
function studentHome(){const c=activeChapter();if(data.course.chapters.every(x=>chapterCleared(x.id)))return `<section class="student-course card"><h1>Course chapters completed</h1><p>You have passed all fourteen chapter assessments.</p><a class="btn primary" href="#exam">Take the final examination →</a><details><summary>Review completed chapters</summary>${data.course.chapters.map(c=>`<p><a href="#watch/${c.id}">${escape(c.title)}</a></p>`).join('')}</details></section>`;return studentWatch(c.id);}
function studentRead(id){const c=data.course.chapters.find(x=>x.id===id);return chapterLayout(id,'reading',`<article class="course-content-card"><div class="course-reading-header"><h2>Chapter reading</h2><a class="course-text-link" href="${asset(c.bookUrl)}" target="_blank" rel="noopener">Open reading in a full tab ↗</a></div><iframe title="Complete chapter reading" class="course-book-reader" src="${asset(c.bookUrl)}"></iframe><div class="course-lesson-footer"><button class="btn primary" data-complete-lesson="reading" data-chapter="${id}">${readingDone(id)?'Continue to assessment →':'Mark chapter as read →'}</button></div></article>`);}
function studentPractice(id,assessment=false){const l=data.learning.chapters.find(c=>c.id===id),index=l.steps.findIndex(s=>s.kind===(assessment?'assessment':'challenge')),record=chapterProgress['r-agriculture_'+id]||{};if(!assessment&&!drafts[id]&&!record.draft)drafts[id]=l.steps[index].code;return assessment?chapterLayout(id,'assessment',workshop(id,index)):`<a class="course-back" href="#read/${id}">← Back to chapter</a>`+workshop(id,index);}
