function home(){const st=stats();return `<section class="wine-welcome card"><div class="wine-card-header">▷ Getting started</div><div class="wine-card-body"><span class="eyebrow">WELCOME TO YOUR LEARNING SPACE</span><h1>Hello, ${escape(session.user.name.split(' ')[0])}.</h1><h2>R Programming for Agricultural Data Analysis</h2><p>Read your textbook, explore topic-wise lectures, experiment in R and discuss your reasoning with STAT MAASH.</p><div class="wine-actions"><a class="btn primary" href="#chapters">▤ Explore lectures</a><a class="btn wine-info" href="#exam">? Take assessment</a><a class="btn wine-warning" href="#progress">◷ Course progress</a><a class="btn green" href="#library">▥ Read the book</a></div><div class="wine-guidelines"><h3>Your course, at your pace</h3><ul><li><strong>Read:</strong> complete chapter explanations, figures and worked examples.</li><li><strong>Experiment:</strong> predict an output, run R and change an input.</li><li><strong>Discuss:</strong> ask STAT MAASH to explain your code and results.</li><li><strong>Assess:</strong> practise topic questions and complete chapter checkpoints.</li></ul></div></div></section><div class="wine-dashboard-tiles"><a href="#chapters"><span>14</span><strong>Chapter lectures</strong><small>Topic-wise explanations & practice</small></a><a href="#library"><span>▥</span><strong>Complete textbook</strong><small>Your original book in one place</small></a><a href="${nextLesson()}"><span>&gt;_</span><strong>Interactive R laboratory</strong><small>Code, console, plots & AI mentor</small></a></div><section class="card wine-course-list"><div class="section-row"><h2>Explore your lectures</h2><a class="btn subtle small" href="#chapters">All chapters →</a></div>${data.course.chapters.map(c=>`<a class="wine-lecture-row" href="#watch/${c.id}"><span>${c.id}</span><div><strong>${escape(c.title)}</strong><small>${escape(c.module)}</small></div><b>Open lecture →</b></a>`).join('')}</section><footer class="wine-footer">Department of Agricultural Statistics · Kerala Agricultural University<br><small>STAT MAASH — Mentor AI for Academic Success and Help</small></footer>`;}
function legacyPath(){const s=stats();const groups=[['Foundations','Get comfortable with R','✦','#8054df','#f1ebff',['01','02','03']],['Prepare your data','Turn observations into useful data','▦','#199b8b','#e3f6f2',['04','05']],['Explore & explain','Find the story in your data','◈','#dc9250','#fff2e5',['06','07','08']],['Model change','Growth, time, and forecasting','⌁','#527fdb','#eaf0ff',['09','10']],['Statistical thinking','Evidence for agricultural decisions','⌘','#bf64a6','#faeafa',['11','12','13']],['Share your science','Reproducible research and AI','✓','#269e72','#e6f6ed',['14']]];return `<section class="hero"><div><span class="pill purple">YOUR R LEARNING JOURNEY</span><h1>A little practice.<br><em>A lot of possibility.</em></h1><p>Welcome back, ${escape(session.user.name.split(' ')[0])}. Every idea is a chance to experiment. Let’s make your next discovery.</p><a class="btn primary" href="${nextLesson()}">Continue learning →</a><p><small>${s.chapters} of 14 chapters complete · ${s.n} activities explored</small></p></div><div class="hero-art">${mascot}<span class="float-tag">✦ Your next discovery is waiting</span><span class="float-tag">&gt; grow_your_skills()</span></div></section><div class="home-grid"><section><div class="section-row"><div><h2>Your learning path</h2><a href="#chapters" class="btn subtle small">Browse all lectures →</a><p>Learn a concept. Run the code. Check your understanding.</p></div><span class="pill mint">${s.xp} LEARNING XP</span></div>${groups.map((g,i)=>`<article class="path-unit" style="--unit:${g[3]};--unit-bg:${g[4]};--unit-shadow:${g[3]}"><div class="unit-header"><span class="unit-badge">${g[2]}</span><div><span class="eyebrow" style="color:${g[3]}">UNIT ${i+1}</span><h3>${g[0]}</h3><small>${g[1]}</small></div></div><div class="path-body">${g[5].map(id=>{const c=data.course.chapters.find(c=>c.id===id);const l=data.learning.chapters.find(c=>c.id===id);const n=passed(id).length;return `<a class="chapter-node ${completed(c)?'complete':''}" href="#study/${id}"><span class="node-circle">${completed(c)?'✓':Number(id)}</span><strong>${escape(c.title)}</strong><small>${n} / ${l.steps.length} activities${data.ratings?.['r-agriculture_'+id]?' · '+data.ratings['r-agriculture_'+id].score+'/'+data.ratings['r-agriculture_'+id].total+' check':''}</small></a>`;}).join('')}</div></article>`).join('')}</section><aside class="path-aside"><article class="card coach-card">${mascot}<span class="eyebrow">MEET YOUR MENTOR</span><h3 style="margin-top:13px">STAT MAASH</h3><p>Mentor AI for Academic Success and Help</p><p>Stuck on a line of code? Bring your question, your attempt, and a little curiosity. We’ll work through it together.</p></article><article class="card"><span class="pill amber">✦ YOUR GROWTH</span><h3 style="margin-top:18px">Understanding takes practice.</h3><div class="stat-row"><span>Course journey</span><strong>${Math.round(s.n/s.total*100)}%</strong></div><div class="meter"><i style="width:${100*s.n/s.total}%"></i></div><div class="stat-row"><span>Chapters completed</span><strong>${s.chapters} / 14</strong></div><div class="stat-row"><span>Practical challenges</span><strong>${data.learning.chapters.filter(c=>passed(c.id).includes(c.id+'-lab')).length} / 14</strong></div><p>XP celebrates completed activities. It is separate from examination marks.</p></article><article class="card"><span class="feature-icon">▤</span><h3>The complete book, always nearby.</h3><p>Go deeper with the author’s full explanations, worked examples, and references.</p><a class="btn subtle small" href="#library">Open your library →</a></article></aside></div>`;}
