function topicGroups(id){const l=data.learning.chapters.find(x=>x.id===id);const groups=[];for(const [index,step] of l.steps.entries()){if(!['learn','code'].includes(step.kind))continue;let g=groups.at(-1);if(!g||g.title!==step.title){g={title:step.title,items:[],first:index};groups.push(g);}g.items.push({...step,index});}return groups;}
