function bookView(id){const c=data.course.chapters.find(c=>c.id===id)||data.course.chapters[0];return `<div class="workspace-heading"><div><span class="eyebrow">THE COMPLETE TEXTBOOK · ORIGINAL EDITION</span><h1>${escape(c.title)}</h1></div><div class="study-actions"><a class="btn subtle small" href="#watch/${c.id}">Chapter study desk</a><a class="btn primary small" href="#learn/${c.id}">Open R & mentor →</a></div></div><div class="reader-layout"><aside class="study-toc"><span class="eyebrow">CONTENTS</span><a href="${asset('books/r-agriculture/index.html')}" target="book-reader">Book introduction</a>${data.course.chapters.map(x=>`<a href="#book/${x.id}" class="${x.id===c.id?'active':''}">${x.id} · ${escape(x.title)}</a>`).join('')}<hr>${[['course-guide','Course guide'],['data-dictionary','Data dictionary'],['glossary','Glossary'],['references','References']].map(([file,label])=>`<a href="${asset('books/r-agriculture/'+file+'.html')}" target="book-reader">${label}</a>`).join('')}</aside><iframe name="book-reader" class="book-frame" title="Complete textbook reader" src="${asset(c.bookUrl)}"></iframe></div>`;}
function current(){return lesson.steps[stepIndex];}
function workshop(id,number){chapter=data.course.chapters.find(c=>c.id===id)||data.course.chapters[0];lesson=data.learning.chapters.find(c=>c.id===chapter.id);const record=chapterProgress['r-agriculture_'+chapter.id]||{};stepIndex=number!==undefined?Math.max(0,Math.min(Number(number)||0,lesson.steps.length-1)):Math.max(0,lesson.steps.findIndex(s=>!passed(chapter.id).includes(s.id)));selected=null;checked=false;chat=chatByChapter[chapter.id]||record.messages||[];drafts[chapter.id]??=record.draft||chapter.code;const step=current();return `<div class="workspace-heading"><div><a class="eyebrow" href="#home">← YOUR LEARNING PATH</a><h1>${escape(chapter.title)}</h1><small>Chapter ${Number(chapter.id)} · ${escape(chapter.module)} · ${passed(chapter.id).length}/${lesson.steps.length} activities</small></div><div class="workspace-actions"><a href="#book/${chapter.id}" class="btn subtle small">▤ Full chapter</a><a href="${asset(chapter.deckUrl)}" class="btn small" download>↓ PPTX</a><button id="reset-session" class="btn small">Reset R</button></div></div><div class="trail-bar"><label>Jump to concept <select id="activity-picker">${lesson.steps.map((s,i)=>`<option value="${i}" ${i===stepIndex?'selected':''}>${passed(chapter.id).includes(s.id)?'✓ ':''}${i+1}. ${escape(s.title||s.prompt)}</option>`).join('')}</select></label><span class="save-indicator" id="save-status">Progress saved to your account</span></div><div class="lab-layout"><section class="lesson-pane"><div class="pane-title">YOUR NEXT SMALL STEP <span>${stepIndex+1} / ${lesson.steps.length}</span></div><div class="step-progress">${lesson.steps.map((s,i)=>`<i class="${passed(chapter.id).includes(s.id)?'done':i===stepIndex?'current':''}"></i>`).join('')}</div><div class="activity" id="activity">${activityHTML(step)}</div><div class="activity-footer"><button class="btn small" id="previous" ${stepIndex===0?'disabled':''}>← Back</button><small>Take your time. Understanding matters.</small><button class="btn green small" id="continue">${step.kind==='check'?'Check answer':'Continue →'}</button></div></section><section class="r-pane"><div class="pane-title">YOUR R PRACTICE <span>WRITE → RUN → UNDERSTAND</span></div><div class="editor-toolbar"><span>script.R <span id="run-status" class="run-status"> · Ready when you are</span></span><button class="btn green small" id="run-r">▶ Run my code</button><button class="btn small" id="stop-r" hidden>Stop</button></div><div class="editor-wrap"><pre class="highlight" id="highlight" aria-hidden="true"></pre><span class="editor-gutter" id="gutter" aria-hidden="true"></span><textarea class="editor" id="editor" aria-label="R code editor" spellcheck="false" autocapitalize="off" autocomplete="off" wrap="off">${escape(drafts[chapter.id])}</textarea></div><div class="file-toolbar"><label class="btn small">↑ Import CSV<input id="csv-upload" type="file" accept=".csv" hidden></label><button class="btn small" id="download-script">↓ Save script</button><small>Ctrl + Enter to run</small></div><details class="r-tools"><summary>Extra tools: packages</summary><div class="package-toolbar"><label for="r-package">Packages</label><select id="r-package"><option>dplyr</option><option>ggplot2</option><option>readxl</option><option>forecast</option><option>DT</option></select><button id="install-package" class="btn small">Install in R session</button></div></details><div class="output-tabs"><button data-output="console" class="active">Results</button><button data-output="plots">Plots <span id="plot-count"></span></button><button data-output="environment">My objects</button></div><pre class="console-output" id="console" role="log">${escape(consoleText||'Your results will appear here.\n1. Read the task.\n2. Complete the code above.\n3. Select Run my code.\nNeed help? Ask STAT MAASH below.')}</pre><div class="r-plots" id="plots" hidden></div><pre class="environment" id="environment" hidden>${escape(environment||'Run R code to inspect your objects.')}</pre><form class="console-form" id="console-form"><span>&gt;</span><input id="console-command" aria-label="R console command" placeholder="Try a command, for example mean(c(3, 4, 5))" autocomplete="off"><button aria-label="Run console command">↵</button></form></section><aside class="coach-pane"><div class="coach-head">${mascot}<div><h3>STAT MAASH</h3><small>YOUR AI LEARNING COMPANION</small></div></div><div class="chat-messages" id="chat-messages">${chatHTML()}</div><div class="quick-prompts"><button data-ask="Give me a hint for this activity. Do not give the full solution.">Give me a hint</button><button data-ask="Explain my R output and any errors. What should I try next?">Explain my output</button><button data-ask="Ask me a short question to test my understanding of this concept.">Test my understanding</button></div><form class="chat-compose" id="chat-form"><textarea id="question" aria-label="Ask STAT MAASH" maxlength="1600" placeholder="Ask a question. Share your thinking…"></textarea><button class="btn primary" id="ask-tutor">Ask STAT MAASH ✦</button><div class="privacy-note">When you ask, your current activity, code, console transcript, and recent conversation are shared with the AI teacher. Never enter personal or confidential data.</div></form></aside></div>`;}
function activityHTML(s){const labels={learn:'✦ DISCOVER',code:'⌘ PREDICT & TRY',check:'✓ QUICK CHECK',challenge:'⚑ YOUR PRACTICAL CHALLENGE',reflect:'✧ EXPLAIN & REFLECT',explore:'◈ CHANGE IT. SEE IT.',assessment:'✓ YOUR CHAPTER CHECKPOINT'};let html=`<span class="pill ${s.kind==='check'?'amber':s.kind==='challenge'?'mint':'purple'}">${labels[s.kind]}</span><h2>${escape(s.title||s.prompt)}</h2>`;if(s.kind==='check')html+=`<p style="font-size:12px;color:var(--muted)">Choose an answer, then check your reasoning.</p>${s.options.map((x,i)=>`<button class="answer-choice" data-answer="${i}"><b>${String.fromCharCode(65+i)}</b>${escape(x)}</button>`).join('')}<div id="check-feedback" role="status"></div>`;else{html+=`<div class="prose">${markdown(s.body)}</div>`;if(s.code)html+=`<pre class="snippet">${escape(s.code)}</pre><button class="btn primary small" id="load-code">Load into workspace →</button><p><small>Predict what happens before you run it.</small></p>`;if(s.kind==='assessment')html+=`<form id="chapter-checkpoint">${s.questions.map(q=>`<fieldset class="exam-question"><legend>${escape(q.prompt)}</legend>${q.options.map((option,i)=>`<label><input type="radio" name="${q.id}" value="${i}" required>${escape(option)}</label>`).join('')}</fieldset>`).join('')}<button class="btn primary small">Check my understanding</button></form><div id="chapter-feedback" role="status"></div>`;if(s.kind==='challenge')html+=`<button class="btn subtle small" id="check-code">Check my result ✓</button><div id="challenge-feedback" role="status"></div><details style="margin-top:20px"><summary>Need a hint?</summary><p>${escape(s.hint)}</p></details>`;if(s.kind==='explore')html+=`<div class="explorer"><label for="explore-value">${escape(s.parameter)} <strong id="parameter-value">${s.value}</strong></label><input type="range" id="explore-value" min="${s.min}" max="${s.max}" step="${s.increment}" value="${s.value}"><p><small>Move the slider. Predict the effect. Then test your idea in real R.</small></p><button class="btn primary small" id="run-explorer">Explore in R →</button></div>`;if(s.kind==='reflect')html+='<textarea class="reflection" id="reflection" aria-label="Your explanation" placeholder="In this chapter, I learned…\nFor an agricultural problem, this means…"></textarea><button class="btn subtle small" id="review-reflection">Ask STAT MAASH to review</button>';if(s.kind==='learn')html+='<button class="link-button" id="listen-card">▶ Listen to this explanation</button><small> · browser voice</small>';}
return html;}
function chatHTML(){return chat.length?chat.map(m=>`<div class="message ${m.role==='student'?'student':''}">${m.role==='student'?escape(m.text):markdown(m.text)}</div>`).join(''):`<div class="message">Hi ${escape(session.user.name.split(' ')[0])}! I’m STAT MAASH. Start with the activity on the left. When you run R, I can help you understand its output. What do you think will happen?</div>`;}
function highlight(){const e=$('#editor');if(!e)return;let code=e.value;$('#highlight').innerHTML=code.split('\n').map(line=>{let tokens=[];line=line.replace(/("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|#.*$)/g,m=>`@@${tokens.push({kind:m.startsWith('#')?'comment':'str',text:m})-1}@@`);line=escape(line).replace(/\b(\d+(?:\.\d+)?)\b/g,'<span class="num">$1</span>').replace(/\b([a-zA-Z_.][\w.]*)\s*(?=\()/g,'<span class="fun">$1</span>');return line.replace(/@@(?:<span class="num">)?(\d+)(?:<\/span>)?@@/g,(_,n)=>`<span class="${tokens[n].kind}">${escape(tokens[n].text)}</span>`);}).join('\n')+'\n';$('#gutter').textContent=code.split('\n').map((_,i)=>i+1).join('\n');$('#highlight').scrollTop=e.scrollTop;$('#highlight').scrollLeft=e.scrollLeft;$('#gutter').style.transform=`translateY(-${e.scrollTop}px)`;}
async function getR(){if(!runtimePromise)runtimePromise=(async()=>{const {WebR,ChannelType}=await import('https://webr.r-wasm.org/v0.6.0/webr.mjs');const r=new WebR({channelType:ChannelType.PostMessage,interactive:false});await r.init();return r;})().catch(e=>{runtimePromise=null;throw e;});return runtimePromise;}
async function execute(code,source='script'){if(running)return;running=true;const context=chapter.id;const run=$('#run-r');if(run)run.disabled=true;if($('#stop-r'))$('#stop-r').hidden=false;if($('#run-status'))$('#run-status').textContent=' · Starting R / running…';consoleText+='\n'+(source==='console'?'> '+code:'> Running script.R')+'\n';let shelter;try{const r=await getR();shelter=await new r.Shelter();const result=await shelter.captureR(code,{withAutoprint:true,captureConditions:false,captureGraphics:{width:740,height:480}});let text='';for(const x of result.output){if(typeof x.data==='string')text+=x.data+'\n';else if(x.data?.toJs){try{text+=JSON.stringify(await x.data.toJs())+'\n';}catch{text+='R condition raised.\n';}}}consoleText+=text||'(Completed without printed output.)\n';lastRun={code,output:text,chapterId:context};for(const image of result.images)plots.push(image);environment=await r.evalRString('paste(capture.output(str(as.list(.GlobalEnv), max.level=1)), collapse="\\n")');if(context===chapter.id){const key='r-agriculture_'+context;chapterProgress[key]??={};chapterProgress[key].codeRuns=(chapterProgress[key].codeRuns||0)+1;scheduleSave();}if($('#run-status'))$('#run-status').textContent=' · Run complete';if(result.images.length)setOutput('plots');}catch(e){consoleText+='Error: '+e.message+'\n';lastRun={code,output:e.message,chapterId:context};if($('#run-status'))$('#run-status').textContent=' · Review the error; try again';}finally{await shelter?.purge().catch(()=>{});running=false;if($('#stop-r'))$('#stop-r').hidden=true;if($('#run-r'))$('#run-r').disabled=false;if($('#console')){$('#console').textContent=consoleText;$('#console').scrollTop=$('#console').scrollHeight;$('#environment').textContent=environment;drawPlots();}}}
function drawPlots(){if(!$('#plots'))return;$('#plots').replaceChildren();for(const image of plots){const canvas=document.createElement('canvas');canvas.width=image.width;canvas.height=image.height;canvas.setAttribute('role','img');canvas.setAttribute('aria-label','Plot produced by your R code');canvas.getContext('2d').drawImage(image,0,0);$('#plots').append(canvas);}$('#plot-count').textContent=plots.length?'('+plots.length+')':'';}
function setOutput(which){outputTab=which;['console','plots','environment'].forEach(id=>{$('#'+id).hidden=id!==which;});document.querySelectorAll('[data-output]').forEach(b=>b.classList.toggle('active',b.dataset.output===which));}
async function checkCode(){const s=current(),out=$('#challenge-feedback');if(!lastRun||lastRun.chapterId!==chapter.id||lastRun.code!==$('#editor').value){out.innerHTML='<div class="feedback wrong">Load your attempt and run the current script before checking it.</div>';return;}try{const r=await getR();const good=await r.evalRBoolean(`isTRUE(tryCatch({${s.test}}, error=function(e) FALSE))`);out.innerHTML=`<div class="feedback ${good?'':'wrong'}">${good?'✓ Your R result passes this practice check. Explain why the result makes sense.':'Not yet. Check your object names and calculations, then run the script again. '+escape(s.hint)}</div>`;if(good){checked=true;await markStep();}}catch(e){out.innerHTML='<div class="feedback wrong">'+escape(e.message)+'</div>';}}
function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveProgress(),900);}
async function saveProgress(){if(!chapter)return;const id=chapter.id,key='r-agriculture_'+id;const record=chapterProgress[key]||{};const payload={chapterId:id,stepIds:record.stepIds||[],draft:drafts[id]||'',codeRuns:record.codeRuns||0,messages:(chatByChapter[id]||chat||[]).slice(-16)};if($('#save-status'))$('#save-status').textContent='Saving your learning…';saveQueue=saveQueue.catch(()=>{}).then(()=>api('progress',payload));try{await saveQueue;if(chapter?.id===id&&$('#save-status'))$('#save-status').textContent='✓ Saved to your account';}catch(e){if($('#save-status'))$('#save-status').textContent='Not saved — '+e.message;}}
async function markStep(){const key='r-agriculture_'+chapter.id;chapterProgress[key]??={};chapterProgress[key].stepIds=[...new Set([...(chapterProgress[key].stepIds||[]),current().id])];await saveProgress();}
async function continueStep(){const s=current();if(!session.user.admin&&s.kind==='challenge'){if(!checked&&!passed(chapter.id).includes(s.id)){toast('Run your code, then choose Check my result.');return;}location.hash='#read/'+chapter.id;return;}if(!session.user.admin&&s.kind==='assessment'&&checked){await bootstrap();location.hash='#home';return;}if(s.kind==='check'&&!checked){if(selected===null){toast('Choose an answer first.');return;}const good=selected===s.answer;$('#check-feedback').innerHTML=`<div class="feedback ${good?'':'wrong'}"><strong>${good?'✓ You’ve got it.':'Keep thinking.'}</strong><br>${escape(s.explanation)}</div>`;document.querySelector(`[data-answer="${selected}"]`).classList.add(good?'correct':'wrong');if(!good)return;checked=true;$('#continue').textContent='Continue →';await markStep();return;}if(s.kind==='assessment'&&!checked&&!passed(chapter.id).includes(s.id)){toast('Complete your chapter checkpoint first.');return;}if(s.kind==='challenge'&&!checked&&!passed(chapter.id).includes(s.id)){toast('Run your solution and use Check my result first.');return;}if(s.kind==='reflect'&&!$('#reflection').value.trim()){toast('Write a brief reflection before continuing.');return;}await markStep();if(stepIndex<lesson.steps.length-1)location.hash='#learn/'+chapter.id+'/'+(stepIndex+1);else{const next=data.course.chapters[data.course.chapters.indexOf(chapter)+1];$('#activity').innerHTML=`<div class="celebration"><span>✦</span><span class="pill mint">CHAPTER PATH COMPLETE</span><h2>You kept growing.</h2><p>Review any concepts you found difficult. Your next chapter is another opportunity to experiment.</p><a class="btn primary" href="${next?'#learn/'+next.id:'#home'}">${next?'Next chapter →':'Return to your pathway →'}</a></div>`;$('#continue').disabled=true;}}
async function ask(question){if(!question.trim())return;const context=chapter.id,step=current(),thread=chat;const button=$('#ask-tutor');button.disabled=true;thread.push({role:'student',text:question});chatByChapter[context]=thread;$('#chat-messages').innerHTML=chatHTML()+'<div class="message" id="thinking">STAT MAASH is thinking…</div>';$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;const payload={courseId:data.course.id,chapterId:context,activityId:step.id,question,activity:(step.title||step.prompt)+'\n'+(step.body||''),code:$('#editor').value,output:lastRun?.chapterId===context?'Executed code:\n'+lastRun.code+'\nTranscript:\n'+lastRun.output:'No execution transcript yet.',history:thread.slice(-8,-1).map(m=>m.role+': '+m.text).join('\n')};try{const response=await api('teach',payload);thread.push({role:'teacher',text:response.answer});chatByChapter[context]=thread;if(chapter?.id===context)scheduleSave();}catch(e){thread.push({role:'teacher',text:e.message});}finally{if(chapter?.id===context&&$('#chat-messages')){$('#chat-messages').innerHTML=chatHTML();$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;$('#ask-tutor').disabled=false;if(window.MathJax?.typesetPromise)window.MathJax.typesetPromise([$('#chat-messages')]).catch(()=>{});}}}

function examPage(){return `<div class="workspace-heading"><div><span class="eyebrow">EVIDENCE OF UNDERSTANDING</span><h1>Assessments</h1></div><span id="exam-timer" class="timer"></span></div><div class="notice">Learning XP and practice checks are formative. The final examination is server-marked, with results held for instructor release. This objective exam does not replace an instructor-led R practical.</div>${exam?`<form id="exam-form">${exam.questions.map((q,i)=>`<fieldset class="exam-question"><legend>${i+1}. ${escape(q.prompt)}</legend>${q.options.map((a,j)=>`<label><input type="radio" name="${q.id}" value="${j}" ${exam.answers[q.id]===j?'checked':''}>${escape(a)}</label>`).join('')}</fieldset>`).join('')}<button class="btn primary">Submit final examination</button><p id="exam-save" role="status"></p></form>`:`<div class="card"><h2>Your final chapter check</h2><p>14 questions · 25 minutes · One attempt. Complete your chapter pathway before starting. STAT MAASH is unavailable during an active exam.</p><button class="btn primary" id="start-exam">Start / resume examination →</button></div><section class="card" style="margin-top:24px"><h2>Your assessment records</h2><div id="attempts" class="empty">Loading your records…</div></section>`}`;}
function examAnswers(){return Object.fromEntries(Array.from(new FormData($('#exam-form')).entries()).map(([k,v])=>[k,Number(v)]));}
function adminPage(){if(!session.user.admin)return '<section class="card gate"><h2>Administrator access required.</h2></section>';return `<span class="eyebrow">TEACHER WORKSPACE</span><div class="section-row"><div><h1>Your teacher dashboard.</h1><p>Approve access, follow learning, and release examination results.</p></div><button class="btn subtle" id="refresh-admin">Refresh ↻</button></div><section class="card"><h2>Chapter video lectures</h2><p>Add your lecture video for each chapter. Use a YouTube, Vimeo, or direct MP4/WebM link.</p><form id="lecture-video-form" class="lecture-video-form"><label>Chapter<select id="lecture-chapter">${data.course.chapters.map(c=>`<option value="${c.id}">${c.id} · ${escape(c.title)}</option>`).join('')}</select></label><label>Video link<input id="lecture-url" type="url" placeholder="https://…" value="${escape(data.videos?.['01']?.url||'')}"></label><button class="btn primary small">Save video lecture</button></form><p id="lecture-save-status" role="status"></p><small>Leave the link empty to remove a video. Until a video is added, students can continue with the chapter reading.</small></section><section class="card"><div class="section-row"><h2>Student attendance, progress & scores</h2><a class="btn primary small" href="/api/scores.csv" download>Download scores CSV ↓</a></div><div id="student-report" class="table-wrap">Loading learning records…</div><small>Active now = a visible course tab reported activity in the last 2 minutes. Activity refreshes every minute. Recorded minutes are indicative course use.</small></section><section class="card"><h2>Student approval queue</h2><p>Only email-verified, approved students can enter the classroom. Suspension takes effect on their next protected request.</p><div id="students" class="table-wrap">Loading registrations…</div></section><section class="card" style="margin-top:24px"><h2>Examination review</h2><div id="results" class="table-wrap">Loading results…</div></section><section class="card" style="margin-top:24px"><h2>Grow your book library</h2><p>Import a prepared JSON course manifest. Imported books are available only to approved students. Reviewed interactive activities must be prepared for each new book.</p><form id="import-form"><label>Course manifest <input type="file" id="manifest" accept=".json" required></label><button class="btn primary small" style="margin-top:15px">Import book</button></form><p id="import-status" role="status"></p></section>`;}
async function loadAdmin(){try{const report=await api('student-report');$('#student-report').innerHTML=report.students.length?'<p class="attendance-summary"><strong>'+report.students.filter(p=>p.activeNow).length+' active now</strong> · '+report.students.length+' students</p><table class="admin-table"><thead><tr><th>Student</th><th>Course activity</th><th>WhatsApp</th><th>Chapters passed</th><th>Lecture / reading completed</th><th>Chapter scores (latest)</th><th>R runs</th><th>Final</th></tr></thead><tbody>'+report.students.map(p=>{const scores=Object.values(p.scores),exam=report.exams.find(x=>x.uid===p.uid);return '<tr><td>'+escape(p.name)+'<br><small>'+escape(p.email)+'</small><br><small>'+escape(p.rollNo||'Profile incomplete')+' · '+escape(p.degree||'')+'</small></td><td><strong>'+(p.activeNow?'● Active now':'Not active now')+'</strong><br><small>'+(p.lastActiveAt?new Date(p.lastActiveAt).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}):'Not started')+'</small><br><small>'+(p.currentChapter?'Chapter '+escape(p.currentChapter)+' · '+escape(p.currentSection):'')+'</small><br><small>'+p.activeMinutes+' recorded min · '+p.attendanceDays+' days</small></td><td>'+escape(p.whatsapp)+'</td><td>'+scores.filter(x=>x.passed||(x.total>0&&x.score===x.total)).length+' / 14</td><td>'+'Video '+Object.values(p.progress).filter(x=>x.videoComplete).length+' · Reading '+Object.values(p.progress).filter(x=>x.readComplete).length+'</td><td>'+scores.map(x=>escape(x.chapterId)+': '+x.score+'/'+x.total+(x.passed?' ✓':'')).join(' · ')+'</td><td>'+Object.values(p.progress).reduce((a,x)=>a+(x.codeRuns||0),0)+'</td><td>'+(exam?String(exam.score??'—')+'/'+exam.total+' · '+escape(exam.status):'Not started')+'</td></tr>';}).join('')+'</tbody></table>':'<p>No student records yet.</p>';const [people,results]=await Promise.all([api('students'),api('reviewAttempts',{})]);$('#students').innerHTML=people.students.filter(p=>!p.isTeacher).length?`<table class="admin-table"><thead><tr><th>STUDENT</th><th>EMAIL</th><th>STATUS</th><th>ACCESS</th></tr></thead><tbody>${people.students.filter(p=>!p.isTeacher).map(p=>`<tr><td>${escape(p.name)}<br><small>${escape(p.rollNo||'Profile incomplete')} · ${escape(p.degree||'')}</small><br><small>WhatsApp: ${escape(p.whatsapp||'—')}</small></td><td>${escape(p.email||'')}</td><td><span class="pill ${p.status==='approved'?'mint':'amber'}">${escape(p.status)}</span></td><td><button class="btn small" data-approve="${escape(p.uid)}" data-status="approved" ${!p.profileComplete?'disabled title="Student details are required"':''}>Approve</button><button class="btn danger small" data-approve="${escape(p.uid)}" data-status="suspended">Suspend</button></td></tr>`).join('')}</tbody></table>`:'<p class="empty">New student registrations will appear here for review.</p>';$('#results').innerHTML=attemptsHTML(results.attempts,true);document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('approval',{uid:b.dataset.approve,status:b.dataset.status});toast('Student access updated.');await loadAdmin();}catch(e){toast(e.message);b.disabled=false;}});document.querySelectorAll('[data-release]').forEach(b=>b.onclick=async()=>{try{await api('releaseResult',{attemptId:b.dataset.release});await loadAdmin();}catch(e){toast(e.message);}});}catch(e){$('#students').textContent=e.message;}}
function attemptsHTML(items,admin=false){if(!items.length)return '<p class="empty">No assessment records yet.</p>';return `<table class="admin-table"><thead><tr>${admin?'<th>STUDENT</th>':''}<th>TYPE</th><th>RESULT</th><th>STATUS</th>${admin?'<th>ACTION</th>':''}</tr></thead><tbody>${items.map(a=>`<tr>${admin?`<td>${escape(a.name)}</td>`:''}<td>${escape(a.type)}</td><td>${a.score??'—'} / ${a.total}</td><td>${escape(a.status)}</td>${admin?`<td>${a.status==='provisional'?`<button class="btn small" data-release="${escape(a.id)}">Release result</button>`:''}</td>`:''}</tr>`).join('')}</tbody></table>`;}
function render(){$('#auth-form [name=name]')?.closest('label').remove();if(!$('#role-badge'))$('#account').insertAdjacentHTML('beforebegin','<span id="role-badge" class="pill purple" hidden></span>');$('#auth-form [name=password]').minLength=6;if(window.MathJax?.typesetClear)window.MathJax.typesetClear([$('#main')]);clearInterval(examTimer);window.speechSynthesis?.cancel();let [route,id,n]=(location.hash.slice(1)||'home').split('/');const requestedRoute=route;const isStudent=!!session&&!session.user.admin;document.body.classList.toggle('student-view',isStudent);document.body.dataset.stage=route;document.querySelectorAll('nav a:not(#admin-nav)').forEach(a=>a.hidden=isStudent);if(isStudent&&data){const unlocked=data.unlocked||data.learning.chapters.map(c=>c.id);if(['watch','read','practise','assess','learn','study','book'].includes(route)&&!unlocked.includes(id)){route='home';}if(route==='assess'&&!chapterCleared(id)&&!assessmentReady(id))route='read';if(['chapters','library','progress','admin','study','book','learn'].includes(route))route='home';}if(route!==requestedRoute)history.replaceState(null,'',route==='home'?'#home':'#'+route+'/'+id);document.body.dataset.stage=route;$('#admin-nav').hidden=!session?.user.admin;$('#admin-nav').textContent='Teacher';$('#role-badge').hidden=!session;$('#role-badge').textContent=session?.user.admin?'Teacher':'Student';$('#learner-stat').textContent='';$('#account').textContent=session?'Sign out · '+session.user.name.split(' ')[0]:'Sign in ↗';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route||(route==='learn'&&a.hash==='#home')));if(!session)$('#main').innerHTML=landing();else if(!session.access)$('#main').innerHTML=session.needsProfile?studentProfileForm():waiting();else if(!data)$('#main').innerHTML='<div class="boot">Opening approved learning material…</div>';else{const s=stats();$('#learner-stat').textContent='✦ '+s.xp+' XP';$('#main').innerHTML=isStudent&&route==='home'?studentHome():route==='watch'?studentWatch(id):route==='read'?studentRead(id):isStudent&&route==='practise'?studentPractice(id):route==='assess'?studentPractice(id,true):route==='progress'?legacyPath():route==='chapters'?chaptersView():route==='study'?studyView(id,n):route==='learn'?workshop(id,n):route==='library'?library():route==='book'?bookView(id):route==='admin'?adminPage():route==='exam'?examPage():home();}if(session?.access&&data&&!isStudent&&['home','chapters','library','exam','admin','progress'].includes(route)){$('#main').innerHTML='<div class="wine-shell">'+overviewSidebar()+'<div class="wine-content">'+$('#main').innerHTML+'</div></div>';}bind();if(session?.access&&data){if(route==='admin'&&session.user.admin)loadAdmin();if(route==='exam'){if(exam)startTimer();else api('myAttempts',{}).then(r=>{if($('#attempts'))$('#attempts').innerHTML=attemptsHTML(r.attempts);}).catch(e=>toast(e.message));}if(['learn','practise','assess'].includes(route)){highlight();drawPlots();setOutput(outputTab);}}if(window.MathJax?.typesetPromise)window.MathJax.typesetPromise([$('#main')]).catch(()=>{});window.scrollTo(0,0);if(session?.access&&!session.user.admin)recordAttendance();}
function bind(){$('#student-profile-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button');button.disabled=true;try{await api('student-profile',Object.fromEntries(new FormData(form)));await bootstrap();}catch(err){$('#profile-status').textContent=err.message;button.disabled=false;}});document.querySelectorAll('[data-complete-lesson]').forEach(button=>button.onclick=async()=>{const id=button.dataset.chapter,kind=button.dataset.completeLesson;button.disabled=true;try{await api('lesson-completion',{chapterId:id,kind});chapterProgress['r-agriculture_'+id]??={};chapterProgress['r-agriculture_'+id][kind==='reading'?'readComplete':'videoComplete']=true;if(kind==='video')location.hash='#read/'+id;else location.hash=assessmentReady(id)?'#assess/'+id:'#watch/'+id;}catch(err){toast(err.message);button.disabled=false;}});$('#lecture-video-form')?.addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const id=$('#lecture-chapter').value,result=await api('lecture-video',{chapterId:id,url:$('#lecture-url').value.trim()});data.videos??={};data.videos[id]=result.video;$('#lecture-save-status').textContent=result.video?'Video lecture saved.':'Video removed. Reading remains available.';}catch(err){$('#lecture-save-status').textContent=err.message;}finally{button.disabled=false;}});$('#lecture-chapter')?.addEventListener('change',()=>{$('#lecture-url').value=data.videos?.[$('#lecture-chapter').value]?.url||'';$('#lecture-save-status').textContent='';});$('#finish-reading')?.addEventListener('click',async e=>{const b=e.currentTarget,id=b.dataset.chapter,i=Number(b.dataset.topic),groups=topicGroups(id),key='r-agriculture_'+id;chapterProgress[key]??={};const record=chapterProgress[key];record.stepIds=[...new Set([...(record.stepIds||[]),...groups[i].items.map(s=>s.id)])];b.disabled=true;try{await api('progress',{chapterId:id,stepIds:record.stepIds,draft:record.draft||drafts[id]||'',codeRuns:record.codeRuns||0,messages:record.messages||[]});location.hash=i<groups.length-1?'#read/'+id+'/'+(i+1):'#practise/'+id;}catch(err){toast(err.message);b.disabled=false;}});document.querySelectorAll('[data-study-answer]').forEach(b=>b.onclick=()=>{const question=data.learning.chapters.find(c=>c.id===b.dataset.studyChapter).steps[Number(b.dataset.studyCheck)],correct=Number(b.dataset.studyAnswer)===question.answer;document.querySelectorAll('[data-study-answer]').forEach(x=>x.classList.remove('selected','correct','wrong'));b.classList.add(correct?'correct':'wrong');$('#study-check-feedback').innerHTML='<div class="feedback '+(correct?'':'wrong')+'"><strong>'+(correct?'Correct. Explain why.':'Try again after reviewing the explanation.')+'</strong><p>'+escape(question.explanation)+'</p></div>';}); $('#chapter-search')?.addEventListener('input',e=>{let visible=0;document.querySelectorAll('.lecture-card').forEach(card=>{card.hidden=!card.dataset.search.includes(e.target.value.toLowerCase().trim());if(!card.hidden)visible++;});$('#search-empty').hidden=visible>0;});document.querySelectorAll('[data-copy-example]').forEach(b=>b.onclick=async()=>{const code=data.learning.chapters.find(c=>c.id===b.dataset.chapter).steps[Number(b.dataset.copyExample)].code;try{await navigator.clipboard.writeText(code);toast('R code copied.');}catch{toast('Select and copy the code in the example.');}});document.querySelectorAll('.open-auth').forEach(b=>b.onclick=openAuth);$('#resend-verification')?.addEventListener('click',()=>openAuth(true));$('#signout')?.addEventListener('click',signout);$('#refresh-access')?.addEventListener('click',bootstrap);$('#book-chapter')?.addEventListener('change',e=>location.hash='#book/'+e.target.value);$('#activity-picker')?.addEventListener('change',e=>navigateStep(Number(e.target.value)));$('#previous')?.addEventListener('click',()=>navigateStep(stepIndex-1));$('#continue')?.addEventListener('click',continueStep);document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(checked)return;selected=Number(b.dataset.answer);document.querySelectorAll('[data-answer]').forEach(x=>x.classList.toggle('selected',x===b));});$('#explore-value')?.addEventListener('input',e=>$('#parameter-value').textContent=e.target.value);$('#run-explorer')?.addEventListener('click',async()=>{const value=Number($('#explore-value').value);const code=current().template.replaceAll('@VALUE@',String(value));$('#editor').value=code;drafts[chapter.id]=code;highlight();await execute(code);});$('#load-code')?.addEventListener('click',()=>{const code=current().code;if($('#editor').value!==code&&drafts[chapter.id]){drafts[chapter.id+'-backup']=$('#editor').value;}$('#editor').value=code;drafts[chapter.id]=code;highlight();scheduleSave();toast('Example loaded. Edit it, then run the code.');});$('#editor')?.addEventListener('input',()=>{drafts[chapter.id]=$('#editor').value;highlight();scheduleSave();});$('#editor')?.addEventListener('scroll',highlight);$('#editor')?.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const t=e.target;const start=t.selectionStart;t.setRangeText('  ',start,t.selectionEnd,'end');drafts[chapter.id]=t.value;highlight();scheduleSave();}if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();execute($('#editor').value);}});$('#run-r')?.addEventListener('click',()=>execute($('#editor').value));$('#console-form')?.addEventListener('submit',e=>{e.preventDefault();const input=$('#console-command');if(input.value.trim()){execute(input.value,'console');input.value='';}});document.querySelectorAll('[data-output]').forEach(b=>b.onclick=()=>setOutput(b.dataset.output));$('#chapter-checkpoint')?.addEventListener('submit',async e=>{e.preventDefault();const answers=Object.fromEntries(Array.from(new FormData(e.target)).map(([id,v])=>[id,Number(v)]));try{const r=await api('gradeChapter',{courseId:data.course.id,chapterId:chapter.id,answers});data.ratings??={};data.ratings['r-agriculture_'+chapter.id]=r;checked=r.score===r.total;$('#chapter-feedback').innerHTML='<div class="feedback '+(checked?'':'wrong')+'"><strong>'+r.score+' / '+r.total+'</strong><br>'+(checked?'Your answers are correct. Continue when you are ready.':'Revisit the explanations and try again. This is practice, so retries are welcome.')+'</div>';if(checked){await markStep();if(!session.user.admin){$('#chapter-feedback').innerHTML+='<p><a class="btn green" href="#home" id="unlock-next">Chapter cleared — continue →</a></p>';$('#unlock-next').onclick=async e=>{e.preventDefault();await bootstrap();location.hash='#home';};}}}catch(err){toast(err.message);}});$('#check-code')?.addEventListener('click',checkCode);$('#chat-form')?.addEventListener('submit',e=>{e.preventDefault();const q=$('#question');ask(q.value);q.value='';});document.querySelectorAll('[data-ask]').forEach(b=>b.onclick=()=>ask(b.dataset.ask));$('#review-reflection')?.addEventListener('click',()=>ask('Please review my explanation and ask one follow-up question: '+$('#reflection').value));$('#listen-card')?.addEventListener('click',()=>{if(!window.speechSynthesis){toast('Browser speech is unavailable. The complete explanation is shown here.');return;}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance($('#activity .prose').innerText);u.rate=.95;window.speechSynthesis.speak(u);});$('#install-package')?.addEventListener('click',async()=>{const b=$('#install-package'),name=$('#r-package').value;b.disabled=true;toast('Installing '+name+' from the webR package repository…');try{const r=await getR();await r.installPackages([name]);consoleText+='\nPackage '+name+' installed. Use library('+name+') to load it.\n';$('#console').textContent=consoleText;toast(name+' installed in this R session.');}catch(e){toast('Package installation failed: '+e.message);}finally{if($('#install-package'))$('#install-package').disabled=false;}});$('#stop-r')?.addEventListener('click',async()=>{const r=await runtimePromise;await r.close();runtimePromise=null;lastRun=null;toast('R stopped. Run your script to start a new session.');});$('#download-script')?.addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([$('#editor').value],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='chapter-'+chapter.id+'.R';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});$('#csv-upload')?.addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>10000000)throw Error('Choose a CSV under 10 MB.');const name=file.name.replace(/[^a-zA-Z0-9_.-]/g,'_');const r=await getR();await r.FS.writeFile(name,new Uint8Array(await file.arrayBuffer()));const command='uploaded_data <- read.csv('+JSON.stringify(name)+')\nstr(uploaded_data)';await execute(command,'console');toast('CSV imported into this R session. Files are not saved when the session closes.');}catch(err){toast(err.message);}});$('#reset-session')?.addEventListener('click',async()=>{if(running){toast('Wait for the current R command to finish.');return;}if(runtimePromise){const r=await runtimePromise;await r.close();runtimePromise=null;}for(const image of plots)image.close();plots.length=0;lastRun=null;consoleText='R session reset. Your saved script is unchanged.\n';environment='';render();});$('#refresh-admin')?.addEventListener('click',loadAdmin);$('#import-form')?.addEventListener('submit',async e=>{e.preventDefault();try{const file=$('#manifest').files[0];if(file.size>800000)throw Error('Use a manifest under 800 KB.');await api('import',{book:JSON.parse(await file.text())});$('#import-status').textContent='Book imported. Refresh the classroom to load it.';}catch(err){$('#import-status').textContent=err.message;}});$('#start-exam')?.addEventListener('click',async()=>{try{exam=await api('startExam',{courseId:data.course.id});render();}catch(e){toast(e.message);}});$('#exam-form')?.addEventListener('change',()=>{exam.answers=examAnswers();const snapshot={...exam.answers};examQueue=examQueue.catch(()=>{}).then(()=>api('saveExam',{attemptId:exam.id,answers:snapshot})).then(()=>{if($('#exam-save'))$('#exam-save').textContent='✓ Answers saved';}).catch(e=>{if($('#exam-save'))$('#exam-save').textContent=e.message;});});$('#exam-form')?.addEventListener('submit',async e=>{e.preventDefault();await submitExam();});}
function navigateStep(n){clearTimeout(saveTimer);if(chapter){drafts[chapter.id]=$('#editor').value;saveProgress();}location.hash='#learn/'+chapter.id+'/'+n;}
function startTimer(){const tick=()=>{if(!exam)return;const left=Math.max(0,Math.floor((exam.deadline-Date.now())/1000));if($('#exam-timer'))$('#exam-timer').textContent=`${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`;if(left===0){clearInterval(examTimer);submitExam();}};tick();examTimer=setInterval(tick,1000);}
async function submitExam(){if(!exam)return;const id=exam.id,answers=$('#exam-form')?examAnswers():exam.answers;try{await examQueue;const result=await api('submitExam',{attemptId:id,answers});exam=null;clearInterval(examTimer);render();toast(`Submitted: ${result.score}/${result.total}. Result awaits instructor release.`);}catch(e){toast(e.message);}}
function openAuth(resend=false){resendRequested=resend===true;$('#auth-title').textContent=resendRequested?'Send a fresh verification email':'Welcome to your classroom.';$('#auth-status').textContent=resendRequested?'Confirm your password to send a new link to your registered email.':'';$('#auth-form [type=submit]').textContent=resendRequested?'Sign in and resend':'Sign in';$('#register').hidden=resendRequested;if(resendRequested&&session){$('#auth-form [name=email]').value=session.user.email;}if(!$('#auth-dialog').open)$('#auth-dialog').showModal();}

async function signout(){await api('logout',{});session=null;data=null;chapter=null;chapterProgress={};chat=[];for(const key of Object.keys(drafts))delete drafts[key];for(const key of Object.keys(chatByChapter))delete chatByChapter[key];if(runtimePromise){const r=await runtimePromise.catch(()=>null);await r?.close();runtimePromise=null;}for(const image of plots)image.close();plots.length=0;consoleText='';environment='';lastRun=null;exam=null;render();}
async function authenticate(register=false){const form=$('#auth-form');if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);$('#auth-status').textContent=register?'Requesting your student account…':'Opening your account…';try{const result=await api(register?'register':'login',{...values,resendVerification:resendRequested});if(result.verificationSent)toast('A fresh verification email was sent. Use its newest link.');if(result.verificationError)toast('Signed in, but the verification email could not be sent. Please try again later.');resendRequested=false;lastAttendanceSent=0;form.reset();$('#auth-dialog').close();await bootstrap();}catch(e){$('#auth-status').textContent=e.message;}finally{buttons.forEach(b=>b.disabled=false);}}
let attendanceBusy=false,lastAttendanceSent=0;
async function recordAttendance(){if(attendanceBusy||!session?.access||session.user.admin||!data||document.visibilityState!=='visible'||Date.now()-lastAttendanceSent<30000)return;const [route,id]=location.hash.slice(1).split('/');const sections={home:'video',watch:'video',read:'reading',practise:'practice',assess:'assessment',exam:'final-exam'};if(!sections[route||'home'])return;const chapterId=id||activeChapter().id;if(!(data.unlocked||[]).includes(chapterId))return;attendanceBusy=true;try{await api('attendance',{chapterId,section:sections[route||'home']});lastAttendanceSent=Date.now();}catch{}finally{attendanceBusy=false;}}
async function bootstrap(){try{session=await api('session');if(session.access){data=await api('classroom');chapterProgress=data.progress;}else data=null;}catch(e){if(e.status===401){session=null;data=null;}else{toast(e.message);}}render();}
$('#account').onclick=()=>session?signout():openAuth();$('#close-auth').onclick=()=>$('#auth-dialog').close();$('#auth-form').onsubmit=e=>{e.preventDefault();authenticate();};$('#register').onclick=()=>authenticate(true);$('#reset-password').onclick=async()=>{const email=$('#auth-form [name=email]').value;if(!email){$('#auth-status').textContent='Enter your email first.';return;}try{const r=await api('reset',{email});$('#auth-status').textContent=r.message;}catch(e){$('#auth-status').textContent=e.message;}};
window.addEventListener('hashchange',()=>{if(chapter&&$('#editor')){drafts[chapter.id]=$('#editor').value;clearTimeout(saveTimer);saveProgress();}render();});
render();await bootstrap();setInterval(()=>{if(document.visibilityState!=='visible')return;if(session?.user.admin&&location.hash==='#admin')loadAdmin();else recordAttendance();},60000);
